    id: item.id,
    pass,
    checks: { runOk: turn.exitCode === 0, hit, keyOk },
    skill: item.skill,
    businessSteps,
    toolSequence: info.toolCalls.map((call) => call.tool),
    finalPreview: info.final.slice(0, 200),
    durationMs: turn.ms,
  }
}

